const b = $input.first().json.body || {};
if (String(b.consentement).toLowerCase() !== 'true') {
  throw new Error("Consentement manquant : l'étudiant doit accepter que Passerelle fasse les démarches.");
}
if (!b.etudiant_id) throw new Error('etudiant_id manquant.');
const aides = Array.isArray(b.aides) ? b.aides : String(b.aides || '').split(',').map(a => a.trim()).filter(Boolean);
if (aides.length === 0) throw new Error('Aucune aide cochée.');
const banques = Array.isArray(b.banques) ? b.banques : String(b.banques || '').split(',').map(a => a.trim()).filter(Boolean);
const montant = Number(b.montant) > 0 ? Number(b.montant) : null;
let questionnaire = b.questionnaire_reponses || {};
if (typeof questionnaire === 'string') { try { questionnaire = JSON.parse(questionnaire); } catch (e) { questionnaire = {}; } }
return [{ json: { etudiant_id: b.etudiant_id, aides, banques, montant, questionnaire } }];

const { aides } = $('Vérifier la demande').first().json;
const STATUT = { automatisee: 'en_cours', guidee: 'guidee_a_faire', information: 'proposee' };
const choisies = $input.all().map(i => i.json).filter(d => aides.includes(d.aide_code));
if (choisies.length === 0) throw new Error('Aucune des aides cochées ne correspond aux démarches proposées.');
return choisies.map(d => ({ json: {
  id: d.id,
  cochee: true,
  statut: STATUT[d.niveau] || 'proposee',
  updated_at: new Date().toISOString(),
} }));

const { id, created_at, updated_at, consentement_analyse, consentement_le, ...profil } = $input.first().json;
const toutes = $('Marquer les démarches cochées').all().map(i => i.json);
const auto = toutes.filter(d => d.niveau === 'automatisee');
return [{ json: {
  etudiant_id: id,
  profil,
  demarches: auto.map(d => ({ demarche_id: d.id, aide_code: d.aide_code })),
  nb_automatisees: auto.length,
  nb_guidees: toutes.filter(d => d.niveau === 'guidee').length,
  url_retour: 'https://ema9998989.app.n8n.cloud/webhook/passerelle/resultat-agent',
} }];

// Pour chaque démarche automatisée : quel agent H lancer, avec quel message.
const { etudiant_id, profil, demarches, url_retour } = $("Préparer l'envoi aux agents").first().json;
const { banques, montant, questionnaire } = $('Vérifier la demande').first().json;
const val = v => (v === null || v === undefined || v === '') ? 'non renseigné' : v;
const ouiNon = v => v === true ? 'oui' : (v === false ? 'non' : 'non renseigné');

// Avis d'imposition des parents (lu sur les documents), pour la bourse.
const docsDeposes = $("Lire l'avis d'imposition").all().map(i => i.json).filter(d => d && d.champs_extraits);
const avis = docsDeposes.find(d => d.type === 'avis_imposition') || null;
const a = (avis && avis.champs_extraits) || {};

// Code postal du lieu de résidence : profil (saisi par l'étudiant), sinon adresse du bail, sinon questionnaire.
const q = questionnaire || {};
// Meublé : réponse du questionnaire, sinon ce qui est écrit sur le bail.
const bailLu = (docsDeposes.find(d => d.type === 'bail') || {}).champs_extraits || {};
const meubleBail = /^(true|oui|meubl)/i.test(String(bailLu.meuble ?? bailLu.type_logement ?? '')) ? true : (/^(false|non|vide)/i.test(String(bailLu.meuble ?? '')) ? false : null);
if (q.logement_meuble !== true && q.logement_meuble !== false && meubleBail !== null) q.logement_meuble = meubleBail;
const cpDe = s => (String(s || '').match(/\b\d{5}\b/) || [])[0] || null;
const cp = (/^\d{5}$/.test(String(profil.code_postal || '')) ? String(profil.code_postal) : null)
  || cpDe(profil.adresse_logement) || cpDe(q.code_postal) || cpDe(q.visale_projet_cp_ville) || null;
const mensuel = Number(profil.ressources_12_mois) > 0 ? Math.round(Number(profil.ressources_12_mois) / 12) : null;
const profilBase = [
  "Profil de l'étudiant (données de test du hackathon Passerelle) :",
  `Nom : ${val(profil.nom)}`,
  `Prénom : ${val(profil.prenom)}`,
  `Date de naissance : ${val(profil.date_naissance)}`,
  `Nationalité : ${val(profil.nationalite)}`,
  `Établissement : ${val(profil.etablissement)}`,
  `Formation : ${val(profil.formation)}`,
  `Situation professionnelle : ${val(profil.situation_pro)}`,
  `Salaire net mensuel moyen (€) : ${val(mensuel)}`,
  `Ressources nettes imposables des 12 derniers mois (€) : ${val(profil.ressources_12_mois)}`,
  `Boursier : ${ouiNon(profil.boursier)}`,
  `Adresse du logement : ${val(profil.adresse_logement)}`,
  `Code postal du lieu de résidence : ${val(cp)}`,
  `Type de logement : ${val(profil.type_logement)}`,
  `Logement conventionné : ${val(profil.logement_conventionne)}`,
  `Loyer hors charges (€/mois) : ${val(profil.loyer_hors_charges)}`,
  `Charges (€/mois) : ${val(profil.charges)}`,
].join('\n');

// Tout ce que Hugging Face a lu sur les documents déposés (sans les numéros sensibles).
const SENSIBLES = ['numero_document', 'ine', 'numero_fiscal', 'numero_securite_sociale', 'iban', 'mrz'];
const NOMS_DOCS = { piece_identite: "Pièce d'identité", bail: 'Bail', certificat_scolarite: 'Certificat de scolarité', fiche_paie: 'Fiche de paie', quittance_loyer: 'Quittance de loyer', contrat_alternance: "Contrat d'alternance (CERFA)" };
const documentsTexte = docsDeposes.filter(d => d.type !== 'avis_imposition').map(d => {
  const lignes = Object.entries(d.champs_extraits || {})
    .filter(([k, v]) => !SENSIBLES.includes(k) && v !== null && v !== undefined && v !== '')
    .map(([k, v]) => `- ${k.replace(/_/g, ' ')} : ${typeof v === 'object' ? JSON.stringify(v) : v}`);
  return lignes.length ? `${NOMS_DOCS[d.type] || d.type} :\n${lignes.join('\n')}` : null;
}).filter(Boolean).join('\n\n');
const profilTexte = profilBase
  + (documentsTexte ? `\n\nInformations lues sur les documents déposés par l'étudiant (à utiliser quand le profil dit « non renseigné ») :\n${documentsTexte}` : '')
  + "\n\nRègle : utilise ces informations. Ne demande à l'étudiant que ce qui n'est ni dans le profil ni dans les documents, et n'invente jamais une valeur.";

const avisTexte = avis ? [
  "Avis d'imposition des parents (lu sur le document déposé) :",
  `Année de l'avis : ${val(a.annee_avis)} | Revenus de l'année : ${val(a.annee_revenus)}`,
  `Déclarants : ${val(a.declarants)}`,
  `Revenu fiscal de référence : ${val(a.revenu_fiscal_reference)} €`,
  `Revenu brut global : ${val(a.revenu_brut_global)} €`,
  `Nombre de parts : ${val(a.nombre_parts)}`,
  `Adresse du foyer fiscal : ${val(a.adresse)}`,
].join('\n') : "Avis d'imposition des parents : NON FOURNI.";
const LIBELLES_CROUS = {
  crous_premiere_demande: 'Première demande de bourse', crous_ine: 'INE', crous_niveau_etudes: "Niveau d'études l'an prochain",
  crous_redoublement: 'Redoublement', crous_academie_voeu: "Académie de l'établissement",
};
const crousTexte = Object.keys(q).filter(k => k.startsWith('crous_') || ['nationalite_zone'].includes(k))
  .map(k => `${LIBELLES_CROUS[k] || k} : ${q[k] === true ? 'oui' : q[k] === false ? 'non' : val(q[k])}`).join('\n');

const NOMS_BANQUES = { 'pret-lbp': 'La Banque Postale', 'pret-sg': 'Société Générale', 'pret-cic': 'CIC' };
const listeBanques = banques.map(b => NOMS_BANQUES[b] || b).filter(Boolean);

const AGENTS = {
  apl: {
    agent: 'simulateur-apl-caf',
    site: 'caf.fr',
    message: `${profilTexte}\nLogement meublé : ${q.logement_meuble === true ? 'oui (location meublée)' : q.logement_meuble === false ? 'non (location vide)' : 'non renseigné'}\nSituation familiale : ${({ celibataire: 'célibataire (seul(e))', couple: 'en couple', marie: 'marié(e) ou pacsé(e)' })[q.situation_familiale] || val(q.situation_familiale)} | Enfants à charge : ${val(q.enfants_a_charge)}\nTu vis : ${({ seul: 'seul(e)', couple: 'en couple', colocation: 'en colocation' })[q.mode_occupation] || 'non renseigné'}${q.mode_occupation === 'colocation' ? ` (${val(q.nb_colocataires)} personnes, part du loyer charges comprises : ${val(q.part_loyer_cc)} €)` : ''}\n\nFais la simulation d'aide au logement avec ce profil et renvoie le montant mensuel estimé. Utilise la réponse « logement meublé » telle quelle, sans faire d'hypothèse.`,
    answer_format: { type: 'object', properties: { statut: { type: 'string', enum: ['ok', 'bloque'] }, montant_mensuel: { type: ['number', 'null'] }, type_aide: { type: ['string', 'null'] }, etape_bloquante: { type: ['string', 'null'] }, remarques: { type: 'string' } }, required: ['statut', 'montant_mensuel'] },
  },
  prime_activite: {
    agent: 'simulateur-prime-activite-caf',
    site: 'caf.fr',
    message: `${profilTexte}\nSalaires nets des 3 derniers mois : ${mensuel !== null ? `environ ${mensuel} € par mois` : 'non renseignés'}\nAide au logement perçue : aucune pour l'instant\n\nEstime l'éligibilité et le montant mensuel de la prime d'activité avec le simulateur de la CAF.`,
  },
  bourse_crous: {
    agent: 'simulateur-bourse',
    site: 'etudiant.gouv.fr',
    message: `${profilTexte}\n\n${avisTexte}\n${crousTexte ? `\nRéponses de l'étudiant au questionnaire bourse :\n${crousTexte}\n` : ''}\nFais la simulation de bourse sur critères sociaux du Crous avec le simulateur officiel, à partir du revenu fiscal de référence des parents, et renvoie l'échelon et le montant estimés. Ne crée aucun compte, ne te connecte pas et n'envoie aucun dossier social étudiant. Si une information demandée par le simulateur manque, prends l'hypothèse la plus simple et cite-la dans remarques. Établissement : cherche-le une seule fois dans la liste du simulateur (par son nom, puis dans le département de l'académie indiquée). S'il n'y figure pas (école privée ou nom différent), ne bloque pas : choisis une université publique de la même ville que l'école (sinon du même département), pour garder la même distance avec le domicile des parents : le montant de la bourse dépend des revenus des parents et des points de charge (dont la distance), pas de l'établissement, et écris dans remarques « établissement remplacé par … : vérifier que ta formation est habilitée à recevoir des boursiers ». Va droit au but : pas plus de 3 essais par champ. Si l'avis d'imposition des parents n'est pas fourni, ne simule pas : statut = bloque et explique-le dans etape_bloquante.`,
    answer_format: { type: 'object', properties: { statut: { type: 'string', enum: ['ok', 'bloque'] }, echelon: { type: ['string', 'null'], description: '0bis, 1 à 7, ou non_eligible' }, montant_annuel: { type: ['number', 'null'] }, montant_mensuel: { type: ['number', 'null'] }, points_de_charge: { type: ['number', 'null'] }, etape_bloquante: { type: ['string', 'null'] }, remarques: { type: 'string' } }, required: ['statut', 'echelon', 'montant_annuel', 'remarques'] },
  },
  pret_garanti: {
    agent: 'comparateur-pret',
    site: 'sites des banques',
    message: `${profilTexte}\n\nCompare un prêt étudiant dans ces banques : ${(listeBanques.length ? listeBanques : ['La Banque Postale', 'Société Générale', 'CIC']).join(', ')}.\nMontant : ${montant || 8000} €. Durée : 60 mois. Différé : aucun.`,
  },
};

// Alternant (contrat d'apprentissage ou de professionnalisation) : pas de bourse du Crous, inutile de lancer l'agent.
// La réponse de l'étudiant (étape Situation) prime ; le nom de la formation ne sert que s'il n'a rien répondu.
const alternant = q.statut ? q.statut === 'alternant' : /altern|apprenti/i.test(String(profil.formation || ''));
return demarches.map(d => {
  const cfg = AGENTS[d.aide_code] ? { ...AGENTS[d.aide_code] } : null;
  if (cfg && d.aide_code === 'bourse_crous' && alternant) {
    cfg.message += "\n\nNote : l'étudiant est en alternance. Fais quand même la simulation normalement, puis commence tes remarques par : « Attention : en alternance (contrat d'apprentissage ou de professionnalisation), la bourse du Crous n'est pas versée tant que le contrat est en cours. Ce montant vaut si tu reprends des études hors alternance. »";
  }
  return { json: {
    etudiant_id,
    demarche_id: d.demarche_id,
    aide_code: d.aide_code,
    url_retour,
    agent: cfg ? cfg.agent : '',
    site: cfg ? cfg.site : null,
    message: cfg ? cfg.message : null,
    answer_format: cfg && cfg.answer_format ? cfg.answer_format : null,
  } };
});

// Aide automatisée sans agent H pour l'instant (ex. prêt garanti) : on la renvoie comme bloquée pour que l'étudiant soit guidé.
return $input.all().map(i => i.json.resultat_direct ? ({ json: {
  demarche_id: i.json.demarche_id, etudiant_id: i.json.etudiant_id, site: i.json.site, agent: 'aucun', session_id: null,
  connexion_requise: false, fin: new Date().toISOString(), url_retour: i.json.url_retour, ...i.json.resultat_direct,
} }) : ({ json: {
  demarche_id: i.json.demarche_id,
  etudiant_id: i.json.etudiant_id,
  site: null,
  agent: 'aucun',
  session_id: null,
  statut: 'failed',
  connexion_requise: false,
  fin: new Date().toISOString(),
  etape_bloquante: "Pas encore d'agent H pour cette aide : on te guide pour la faire.",
  url_retour: i.json.url_retour,
} }));

// Le comparateur attend que les autres agents H (APL, prime d'activité) aient fini : H limite à 3 agents en même temps.
const pret = $('Comparateur de prêts ?').first().json;
const occupes = $input.all().map(i => i.json).filter(d => d.id && d.aide_code !== 'pret_garanti');
// 40 tours de 30 s au maximum (20 minutes), puis on lance quand même.
return [{ json: { ...pret, attendre: occupes.length > 0 && $runIndex < 40 } }];

// On renvoie la démarche telle qu'elle était, sans le drapeau d'attente.
const { attendre, ...demarche } = $input.first().json;
return [{ json: demarche }];
